import js from "@eslint/js";
import globals from "globals";
import vitest from "@vitest/eslint-plugin";
import playwright from "eslint-plugin-playwright";
import autoImports from "./.wxt/eslint-auto-imports.mjs";

export default [
  {
    ignores: [
      "output/",
      "coverage/",
      ".wxt/",
      "test-results/",
      "website/_site/",
      "website/vendor/",
      "website/.jekyll-cache/",
    ],
  },

  js.configs.recommended,

  // WXT auto-imported globals (defineContentScript, defineBackground, ...).
  // Generated by `wxt prepare`; regenerated on every `npm install` via postinstall.
  autoImports,

  // Extension code runs in browser/webextension contexts.
  {
    files: ["entrypoints/**/*.js", "lib/**/*.js"],
    languageOptions: {
      globals: {
        ...globals.browser,
        ...globals.webextensions,
      },
    },
  },

  // Node-context files: build configs and scripts.
  {
    files: ["*.config.js", "scripts/**/*.js"],
    languageOptions: {
      globals: {
        ...globals.node,
      },
    },
  },

  // Unit tests (Vitest APIs are imported explicitly; no vitest globals needed).
  {
    ...vitest.configs.recommended,
    files: ["tests/unit/**/*.js"],
    languageOptions: {
      globals: {
        ...globals.node,
        // happy-dom supplies DOM globals (document, window, MouseEvent, ...) at runtime.
        ...globals.browser,
      },
    },
  },

  // E2E tests and their harness.
  {
    ...playwright.configs["flat/recommended"],
    files: ["tests/e2e/**/*.js"],
    languageOptions: {
      globals: {
        ...globals.node,
        // page.evaluate()/frame.evaluate()/addInitScript() callbacks execute in the
        // browser (window, document, localStorage) and may use the `chrome` API.
        ...globals.browser,
        ...globals.webextensions,
      },
    },
  },

  // Rule adjustments for the E2E suite:
  // - Conditional test.skip() is this project's sanctioned way to gate tests per
  //   browser project via adapter capabilities (see tests/AGENTS.md).
  // - Panel tests assert via helpers passed to withPanel(); the expect-expect rule
  //   cannot see assertions made inside those helpers.
  {
    files: ["tests/e2e/**/*.js"],
    rules: {
      "playwright/no-skipped-test": ["warn", { allowConditional: true }],
      "playwright/expect-expect": [
        "warn",
        { assertFunctionNames: ["withPanel"] },
      ],
    },
  },

  // devtools-panel-direct.spec.js is a permanently skipped exploratory test kept
  // as documentation of an attempted undocking approach; its conditionals are
  // debug scaffolding, not test logic.
  {
    files: ["tests/e2e/devtools-panel-direct.spec.js"],
    rules: {
      "playwright/no-skipped-test": "off",
      "playwright/no-conditional-in-test": "off",
    },
  },
];
